      }.compact
    end
  end

  # The data of the message.expired event.
  MessageExpired = Struct.new(:message_id, :external_user_id, :channel, :attempts, keyword_init: true) do
    # Reads an answer (or a webhook payload): a Hash with the wire names as keys.
    def self.from_wire(raw)
