      new(
        message_id: Wire.string(w["message_id"], true),
        external_user_id: Wire.string(w["external_user_id"], true),
        channel: Wire.string(w["channel"], false),
        attempts: Wire.integer(w["attempts"], false),
      )
    end

    # The JSON body of this value; members that are nil are left out.
    def to_wire
      {
        "message_id" => message_id,
        "external_user_id" => external_user_id,
        "channel" => channel,
        "attempts" => attempts,
      }.compact
    end
  end

  # The answer to a send. For a send to one `external_user_id` the other fields describe that recipient; for several
  # users or an audience they are empty and each message is under `recipients`.
  #
  # +recipients+:: One entry per user.
  MessageResult = Struct.new(:message_id, :level, :devices, :status, :deliveries, :recipients, keyword_init: true) do
    # Reads an answer (or a webhook payload): a Hash with the wire names as keys.
    def self.from_wire(raw)
      w = raw.is_a?(Hash) ? raw : {}
      new(
        message_id: Wire.string(w["message_id"], false),
        level: Wire.string(w["level"], true),
        devices: Wire.integer(w["devices"], false),
        status: Wire.string(w["status"], false),
        deliveries: Wire.list(w["deliveries"]) { |x| Wire.object(Delivery, x) },
        recipients: Wire.list(w["recipients"]) { |x| Wire.object(Recipient, x) },
      )
    end

    # The JSON body of this value; members that are nil are left out.
    def to_wire
      {
        "message_id" => message_id,
        "level" => Level.coerce(level),
        "devices" => devices,
        "status" => status,
        "deliveries" => Wire.items(deliveries, "message result deliveries", true) { |x| Wire.input(Delivery, x, "delivery")&.to_wire },
        "recipients" => Wire.items(recipients, "message result recipients", true) { |x| Wire.input(Recipient, x, "recipient")&.to_wire },
      }.compact
    end
  end

  # A message's status and per-device deliveries.
  #
  # +status+:: One of queued, delivered, undeliverable, paging, acked, expired.
  # +acked_at+:: When a page was acknowledged; absent until then.
  # +acked_by+:: Who acknowledged a page: their external user id.
  # +acked_by_name+:: The display name of whoever acknowledged, only when they have one.
  MessageStatus = Struct.new(:message_id, :status, :level, :attempts, :deliveries, :acked_at, :acked_by, :acked_by_name, keyword_init: true) do
    # Reads an answer (or a webhook payload): a Hash with the wire names as keys.
    def self.from_wire(raw)
      w = raw.is_a?(Hash) ? raw : {}
      new(
        message_id: Wire.string(w["message_id"], true),
        status: Wire.string(w["status"], true),
        level: Wire.string(w["level"], true),
        attempts: Wire.integer(w["attempts"], true),
        deliveries: Wire.list(w["deliveries"]) { |x| Wire.object(Delivery, x) },
        acked_at: Wire.time(w["acked_at"]),
        acked_by: Wire.string(w["acked_by"], false),
        acked_by_name: Wire.string(w["acked_by_name"], false),
      )
    end

    # The JSON body of this value; members that are nil are left out.
    def to_wire
      {
        "message_id" => message_id,
        "status" => status,
        "level" => Level.coerce(level),
        "attempts" => attempts,
        "deliveries" => Wire.items(deliveries, "message status deliveries", false) { |x| Wire.input(Delivery, x, "delivery")&.to_wire },
        "acked_at" => Wire.iso8601(acked_at),
        "acked_by" => acked_by,
        "acked_by_name" => acked_by_name,
      }.compact
    end
  end

  # The data of the message.undeliverable event.
