  # Tunes a page (level `page`). A zero or absent field means the hub default.
  #
  # +interval_seconds+:: Seconds between resends (hub default 120).
  # +max_retries+:: Resends before the page expires (hub default 5).
  PageOptions = Struct.new(:interval_seconds, :max_retries, :ack, keyword_init: true) do
    # Reads an answer (or a webhook payload): a Hash with the wire names as keys.
    def self.from_wire(raw)
